import { inject, provideAppInitializer } from '@angular/core';
import { ErrorOverlayService } from '@sagebionetworks/explorers/services';
import { applicationConfig } from '@storybook/angular';
import { ErrorOverlayComponent } from './error-overlay.component';
const meta = {
    component: ErrorOverlayComponent,
    title: 'UI/ErrorOverlay',
};
export default meta;
const showOverlay = (show) => applicationConfig({
    providers: [provideAppInitializer(() => show(inject(ErrorOverlayService)))],
});
export const HttpError = {
    decorators: [
        showOverlay((errorOverlayService) => errorOverlayService.showError('An internal server error occurred. Please try again later.')),
    ],
};
export const AppUpdate = {
    decorators: [
        showOverlay((errorOverlayService) => errorOverlayService.showAppUpdateAvailable('Model AD')),
    ],
};
export const DataUpdate = {
    decorators: [
        showOverlay((errorOverlayService) => errorOverlayService.showDataUpdateAvailable('Model AD')),
    ],
};
